import { AudioOutlined, StopOutlined } from "@ant-design/icons"; // 引入 Stop 图标
import { Button, Input, message } from "antd";
import axios from "axios";
import React, { useEffect, useState } from "react";
import SpeechRecognition, {
    useSpeechRecognition,
} from "react-speech-recognition";
import Speech from "speak-tts";

const { Search } = Input;

// 优先使用环境变量，如果没有则回退到 localhost
const DOMAIN = process.env.REACT_APP_DOMAIN || "http://localhost:5001";

const searchContainer = {
  display: "flex",
  justifyContent: "center",
  alignItems: "center",
  gap: "10px",
};

const ChatComponent = (props) => {
  const { handleResp, isLoading, setIsLoading } = props;

  const [searchValue, setSearchValue] = useState("");
  const [isChatModeOn, setIsChatModeOn] = useState(false); // 控制是否进入“纯语音模式”
  const [isRecording, setIsRecording] = useState(false);   // 控制麦克风状态
  const [speech, setSpeech] = useState(null);              // 存储 TTS 实例

  // Speech Recognition (STT) Setup
  const {
    transcript,
    listening,
    resetTranscript,
    browserSupportsSpeechRecognition,
  } = useSpeechRecognition();

  // 1. 初始化文字转语音 (TTS)
  useEffect(() => {
    const initialized_speech = new Speech();
    initialized_speech
      .init({
        volume: 1,
        lang: "en-US", // 如果你的 PDF 是英文，建议改成 "en-US"
        rate: 1,
        pitch: 1,
        // voice: "Google US English", // 如果不指定，浏览器会用默认声音，兼容性更好
        splitSentences: false,
      })
      .then((data) => {
        console.log("Speech is ready, voices are available", data);
        setSpeech(initialized_speech);
      })
      .catch((e) => {
        console.error("An error occured while initializing : ", e);
      });
  }, []);

  // 2. 监听语音输入：当用户说完话（listening 变为 false）且有内容时，自动发送
  useEffect(() => {
    if (isChatModeOn && !listening && transcript) {
      // 只有在 ChatMode 开启时才自动发送
      const currentQuery = transcript; // 暂存
      resetTranscript(); // 发送前清空，防止重复
      onSearch(currentQuery);
      setIsRecording(false);
    }
  }, [listening, transcript, isChatModeOn]); // 依赖项加入 isChatModeOn

  // 3. AI 说话函数
  const talk = (textToSay) => {
    if (!speech) return;

    // 朗读前先停止录音，防止自己听到自己的声音造成死循环
    SpeechRecognition.stopListening();
    setIsRecording(false);

    speech
      .speak({
        text: textToSay,
        queue: false,
        listeners: {
          onstart: () => {
            console.log("Start speaking");
          },
          onend: () => {
            console.log("End speaking");
            // 关键逻辑：AI 说完话后，自动重新开启录音（实现连续对话）
            if (isChatModeOn) {
                userStartConvo(); 
            }
          },
        },
      })
      .catch((e) => {
        console.error("An error occurred :", e);
      });
  };

  // 4. 用户开始说话（开启下一轮对话）
  const userStartConvo = () => {
    resetTranscript();
    SpeechRecognition.startListening({ continuous: false, language: 'en-US' }); // 确保语言设置正确
    setIsRecording(true);
    message.info("Listening..."); // 给用户一点提示
  };

  // 5. 切换聊天模式
  const chatModeClickHandler = () => {
    const nextMode = !isChatModeOn;
    setIsChatModeOn(nextMode);

    if (nextMode) {
      // 开启模式时，立即开始听
      userStartConvo();
    } else {
      // 关闭模式时，停止一切
      setIsRecording(false);
      SpeechRecognition.stopListening();
      if(speech) speech.cancel(); // 停止正在读的声音
    }
  };

  // 6. 手动控制录音按钮（在 Chat Mode 中）
  const recordingClickHandler = () => {
    if (isRecording) {
      setIsRecording(false);
      SpeechRecognition.stopListening();
    } else {
      userStartConvo();
    }
  };

  // 7. 发送请求给后端
  const onSearch = async (question) => {
    if (!question.trim()) return;

    setSearchValue(""); // 清空输入框（如果是文字输入）
    setIsLoading(true);

    try {
      const response = await axios.get(`${DOMAIN}/chat`, {
        params: { question },
      });

      handleResp(question, response.data);

      // 如果开启了语音模式，让 AI 把答案读出来
      if (isChatModeOn && response.data.ragAnswer) {
        // [修复点] 这里必须取 .ragAnswer，不能传整个 response.data
        talk(response.data.ragAnswer); 
      }

    } catch (error) {
      console.error(`Error: ${error}`);
      handleResp(question, { error: "Failed to fetch response" });
      if (isChatModeOn) talk("Sorry, I encountered an error.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleChange = (e) => {
    setSearchValue(e.target.value);
  };

  // 浏览器不支持语音识别的处理
  if (!browserSupportsSpeechRecognition) {
    return <div>Browser doesn't support speech recognition.</div>;
  }

  return (
    <div style={searchContainer}>
      {/* 只有在非 ChatMode 时才显示文本输入框 */}
      {!isChatModeOn && (
        <Search
          placeholder="Input text"
          enterButton="Ask"
          size="large"
          onSearch={onSearch}
          loading={isLoading}
          value={searchValue}
          onChange={handleChange}
          style={{ width: "400px" }}
        />
      )}

      {/* 切换模式的按钮 */}
      <Button
        type={isChatModeOn ? "primary" : "default"}
        danger={isChatModeOn} // 开启时显示红色，提示状态
        onClick={chatModeClickHandler}
        size="large"
      >
        {isChatModeOn ? "Exit Voice Mode" : "Enter Voice Mode"}
      </Button>

      {/* 只有在 ChatMode 开启时才显示的录音状态按钮 */}
      {isChatModeOn && (
        <Button
          type="primary"
          shape="circle"
          icon={isRecording ? <StopOutlined spin /> : <AudioOutlined />}
          size="large"
          onClick={recordingClickHandler}
          style={{ 
            backgroundColor: isRecording ? "#ff4d4f" : "#1890ff",
            border: "none" 
          }}
        />
      )}
    </div>
  );
};

export default ChatComponent;
